react.usage:
import { UploadTray, type UploadTrayProps } from "./UploadTray";

export function ChatAttachments({ files, upload, onAdd, onRemove }: UploadTrayProps) {
  return (
    <UploadTray files={files} upload={upload} maxSize={25 * 1024 * 1024}
      onAdd={onAdd} onRemove={onRemove} />
  );
}

